-- Demo editorial seed requested for the test catalog.
-- The copy intentionally avoids medical, nutritional and certification claims. Product origin remains the canonical DB value.
-- Each row has its own persona, seasonal hook and craft detail; a shared closing standard keeps tone and provenance consistent.

with editorial(slug,persona,seasonal_hook,craft_detail) as (
 values
 ('abidin-in-yayla-kuzusu-302','Çoban Abidin','Yaylanın ağır ağır büyüyen bereketi','Abidin için işin sırrı hayvanı takvimle hızlandırmak değil, meranın durumunu okuyarak bakım ritmini korumaktır. Sipariş geldiğinde bütün karkas ya da kasap usulü parçalama tercihi baştan netleşir; sakatat ve paket düzeni de aynı hazırlık planına bağlanır.'),
 ('amine-nin-cifte-sari-koy-yumurtasi-305','Amine Yenge','Sabahın kümesten çıkan küçük sürprizi','Amine Yenge yumurtayı yalnız kabuk rengine bakarak ayırmaz; tazelik, kabuk bütünlüğü ve taşıma dayanımı tek tek kontrol edilir. Çifte sarı çıkan yumurtalar ayrı seçilir, küçük partiler halinde hazırlanır ve yolculukta darbe görmemesi için düzenli biçimde yerleştirilir.'),
 ('ata-tohumu-dag-kekigi-suyu-distile-807','Toros Yörük Kadınları','Dağ kekiğinin buhara bıraktığı iz','Bu anlatıda Toros Yörük Kadınlarından öğrenilen damıtma disiplini, kayıtlı üretim coğrafyasındaki dağ kekiğine uyarlanır. Bitkinin kokusunu taşıyan bölüm doğru zamanda seçilir; kazan ısısı ve yoğunlaşma ritmi aceleye getirilmeden takip edilir, parti tamamlandığında berraklık ve koku yeniden kontrol edilir.'),
 ('avasin-cam-damacana-suyu-401','Avaşin köy ekibi','Dağın taşından süzülen berraklık','Avaşin suyunda hikâye süslü bir sağlık iddiasıyla değil, kaynak ve kap disiplinine gösterilen özenle başlar. Cam damacanalar dolum öncesi kontrol edilir, sipariş kadar ürün hazırlanır ve taşıma planı suyun bekleme süresini gereksiz yere uzatmayacak şekilde kurulur.'),
 ('avasin-deresi-canli-alabaligi-ozel-hasat-301','Avaşin balıkçıları','Avaşin’in o günkü bereketi','Derede her gün aynı av sözü verilmez; suyun debisi, hava ve günlük koşullar okunur. Müşteri mevcut günlük avdan ayırma ya da sipariş üzerine av seçeneğini belirler, ardından balığın bütün, temizlenmiş veya fileto hazırlanması ve soğuk paket düzeni sipariş kaydına göre uygulanır.'),
 ('avasin-mese-bali-103','Hüseyin Dayı','Meşe gölgesinin koyu ve sakin özü','Hüseyin Dayı mevsimin kısa penceresinde arılığın çevresini ve balın olgunlaşma işaretlerini izler. Petek aceleyle alınmaz; dinlenme ve süzme aşamasında kokuyu örtecek gereksiz işlemden kaçınılır. Kavanoza giren ürünün amacı tekdüze bir fabrika tadı değil, o sezonun gerçek karakterini taşımaktır.'),
 ('bercelan-yaylasi-bahar-cicek-bali-102','Fatma Ana','İlkbaharın ilk çiçeklerinden gelen altın iz','Fatma Ana bahar balını erken almak yerine yayladaki çiçeklenmenin ritmini bekler. Arıların taşıdığı farklı çiçek kokularının birbirine oturması için peteklerin olgunluğu gözlemlenir; hasat küçük partilerle yapılır ve her parti kendi mevsim tonuyla korunur.'),
 ('buyuk-iskender-corek-otu-tohumu-705','Kozmik Tarlalar','Toprağın küçük siyah tanelere bıraktığı güç değil, karakter','Çörek otu tohumunda gösteriş değil ayıklama sabrı öne çıkar. Hasattan sonra yabancı materyal, kırık tane ve nem riski dikkatle ayrılır; tohumun doğal kokusunu örtecek ağır işlem uygulanmadan kuru ve düzenli biçimde paketlenir.'),
 ('dag-cilegi-yabani-803','Köylü kadınlar','Yazın yamaca sakladığı kırmızı mücevher','Yabani dağ çileği aynı boyda yetişmez ve kolay ezilir. Köylü kadınlar toplarken olgun ama yolculuğa dayanacak taneleri ayırır; ürün geniş kasalarda sıkıştırılmadan taşınır ve küçük partiler halinde hazırlanır. Buradaki değer kusursuz görüntü değil, mevsimin kısa ömürlü tazeliğini koruyabilmektir.'),
 ('daglica-karakovan-petek-bali-101','Arıcı Süleyman Usta','Karakovanın sessizce olgunlaştırdığı petek','Süleyman Usta petek balında kesme anını yalnız doluluğa göre seçmez; peteğin kapanması, kovanın dengesi ve mevsimin gidişi birlikte değerlendirilir. Petek biçimi mümkün olduğunca korunur, kırılan bölümler ayrı tutulur ve kutulama sırasında ezilmeyi azaltacak düzen kurulur.'),
 ('eksi-karadut-suyu-804','Dağ Köy Atölyesi','Karadudun mayhoşluğunu saklayan koyu yudum','Dağ Köy Atölyesi karadudu önce ezik, ham ve aşırı yumuşamış tanelerden ayırır. Meyvenin kendi tadını perdelememek için süreç küçük partilerde yürütülür; süzme, dolum ve soğutma aşamaları aynı günün akışında takip edilir ve her şişe kapanmadan önce görsel kontrol görür.'),
 ('el-isciligi-mese-palamudu-ekmegi-505','Ayşe Teyze','Eski kilerin sabrıyla yoğrulan ekmek','Ayşe Teyze meşe palamudunu doğrudan una çevirmek yerine temizleme, hazırlama ve uygun karışım aşamalarını sabırla yürütür. Hamurun suyu çekmesi beklenir, kıvam elde hissedilerek ayarlanır. Siparişte ekmeğin bütün bırakılması ya da dilimlenmesi seçilebilir ve hazırlık buna göre tamamlanır.'),
 ('el-islemesi-tahta-kasik-ve-yayik-tokmagi-704','Selim Usta','Köy elinin ağaçta bıraktığı nesilden nesile iz','Selim Usta ağacı kesmeden önce damar yönünü okur; kaşıkta ağız dengesi, tokmakta ağırlık ve tutuş hissi ayrı ayrı düşünülür. Yüzey elde tekrar tekrar kontrol edilir, çatlamaya açık bölüm ayrılır. Her parçada küçük farklılıkların kalması kusur değil, doğal malzemenin ve el işçiliğinin imzasıdır.'),
 ('fahrettin-in-sutten-kesilmis-oglagi-303','Fahrettin Usta','Dağ yamacında büyüyen oğlağın sakin ritmi','Fahrettin Usta oğlağın bakımını meranın durumuna, hareketine ve mevsime göre sürdürür. Sipariş aşamasında bütün karkas ya da kasap usulü parçalama seçimi baştan alınır; kesim düzeni, sakatat tercihi ve paket boyu aynı kayıt içinde üreticiye ulaşır, böylece hazırlık son dakikada rastgele verilmiş kararlara kalmaz.'),
 ('gunes-sirri-guzu-yagi-ic-yag-701','Kasap Mahmut','Köy mutfağının ağır ateşe ayırdığı eski malzeme','Kasap Mahmut iç yağı hazırlarken temizleme ve ayıklama işini aceleye getirmez. Kullanıma uygun parçalar ayrılır, yabancı doku dikkatle temizlenir ve paketler ev mutfağında yönetilebilir miktarlara göre düzenlenir. Buradaki hikâye mucize vaat etmek değil, eski mutfağın malzemesini temiz ve anlaşılır biçimde ulaştırmaktır.'),
 ('gunluk-taze-civik-sut-sagimdan-kapiya-204','Amine Ana','Soğuk sabahın ilk sağımından gelen beyazlık','Amine Ana için sütte zaman en önemli malzemelerden biridir. Sağım sonrası kap temizliği, hızlı soğutma ve teslimat planı aynı zincirin parçaları olarak ele alınır. Sipariş miktarı önceden bilindiği için gereksiz bekleme azaltılır; ürünün kullanımıyla ilgili güvenlik bilgileri hikâyeden ayrı ve açık biçimde müşteriye gösterilir.'),
 ('hakkari-dag-elmasi-801','Yüksekova bahçecileri','Sonbaharın dalda sertleşen çıtır sesi','Dağ elması toplanırken yalnız renge bakılmaz; sapın tutuşu, kabuğun direnci ve meyvenin taşıma dayanımı birlikte değerlendirilir. Bereli ve yolculuğa uygun olmayan elmalar ayrılır, iyi durumda olanlar katmanlar arasında sıkıştırılmadan kutulanır. Her kasa sonbaharın aynı tonda olmayan ama gerçek karakterini taşır.'),
 ('hardaliye-geleneksel-805','Kırklareli Üretim Kooperatifi','Üzümün eski bir yöntemle ağır ağır değişen yüzü','Bu demo anlatıda Kırklareli Üretim Kooperatifinden öğrenilen geleneksel hardaliye bilgisi, ürünün kayıtlı üretim akışına referans olur. Üzüm seçimi, kap temizliği, bekleme süresi ve parti kontrolü birbirinden ayrılmaz; amaç geleneği romantikleştirmek değil, yöntemin disiplinini anlaşılır biçimde taşımaktır.'),
 ('hatun-ana-nin-eksi-maya-gunesi-tarhana-501','Hatun Ana','Sonbaharın kışa bıraktığı kırmızı kiler güneşi','Hatun Ana tarhanayı tek günde biten bir karışım saymaz. Yoğurma, bekletme, parçalama ve kurutma gün gün izlenir; nemli kalan bölüm yeniden ayrılır. Güneş ve hava uygun değilse süreç uzatılır. Sonunda elde edilen ürün, kış sofrasına açıldığında mevsimini hatırlatacak kadar belirgin ama abartısız bir karakter taşır.'),
 ('havahan-in-otlu-dag-peyniri-203','Havahan Abla','Dağ otlarının süte bıraktığı yeşil iz','Havahan Abla peynirde sütün kıvamını, mayalama anını ve eklenecek otların temizliğini birlikte takip eder. Ot miktarı tadı boğmayacak şekilde ayarlanır; baskı ve dinlendirme aşamalarında peynirin suyunu nasıl bıraktığı izlenir. Küçük parti düzeni her tekerin dokusunu gözle kontrol etmeye imkân verir.'),
 ('husnu-dayi-nin-kagit-kabuklu-cevizi-504','Hüsnü Dayı','Sonbaharın ince kabuğa sakladığı dolgun iç','Hüsnü Dayı cevizde irilikten önce doluluk ve kabuk bütünlüğüne bakar. Hasat sonrası cevizler havadar alanda dinlendirilir; nemini atmamış olanlar paketlemeye alınmaz. İnce kabuklu cevizler kırılmaya daha açık olduğu için yolculukta boşluk yapmayacak ama ürünü ezmeyecek bir düzenle hazırlanır.'),
 ('isli-kaya-uzumleri-tane-kuru-506','Köy kiler ustaları','Üzümün sonbahardan kışa taşıdığı koyu tat','Kurutulacak üzümler arasında ezilmiş ve fazla olgun taneler ayrılır. Isı ve hava, meyvenin dışını yakmadan suyunu azaltacak biçimde yönetilir; hafif odunsu karakter yöntemin bir parçası olarak korunur. Paketlemeden önce taneler yeniden elden geçirilir, yapışma ve nem riski kontrol edilir.'),
 ('kadin-imecesi-odun-atesi-pekmezi-503','Köy kadınlarının imecesi','Bağ bozumunun kazan başında koyulaşan sonbahar hatırası','Pekmez günü tek kişinin işi değildir; üzüm ayıklanır, şıra hazırlanır ve kazan başındaki nöbet paylaşılır. Ateşin bir anda yükselmesi tadı bozabileceği için kıvam gözle ve kaşıkta bıraktığı iz ile takip edilir. Dolum, ürün hâlâ yönetilebilir sıcaklıktayken temiz kaplara yapılır ve her parti ayrı tutulur.'),
 ('kan-kirmizi-yabani-kizilcik-surubu-seti-602','Dağ köyü kadınları','Yaz sonunun mayhoş kızıl hatırası','Yabani kızılcıkta olgunluk aynı dalda bile değişebilir. Meyveler ayıklanır, ezme ve süzme küçük partilerde yapılır; gereksiz aromayla meyvenin doğal mayhoşluğu örtülmez. Sete girecek şişeler dolum seviyesi, kapak ve görünüm açısından yeniden kontrol edilerek birlikte paketlenir.'),
 ('kekik-aromali-kesik-yogurt-kurud-703','Hatun Teyze','Uzun kış yoluna dayanacak eski süt işçiliği','Hatun Teyze kurud hazırlarken ayranın kıvamını kazan başında izler, süzme torbasının ne kadar su bıraktığını el yordamıyla kontrol eder. Tuzlama ve şekillendirme aceleye getirilmez; parçalar kuru ve havadar ortamda sertleşene kadar çevrilir. Son ürün kullanım biçimi anlaşılır olacak şekilde küçük partiler halinde paketlenir.'),
 ('kekik-aromali-visne-kompostosu-809','Köy mutfağı kadınları','Yaz vişnesinin kış sofrasına bıraktığı serin hatıra','Vişneler sap, ezik ve olgunluk bakımından ayıklanır; kaynatma süresi meyveyi tamamen dağıtmadan tadı suya geçirecek biçimde izlenir. Kekik aroması ana meyveyi bastırmayacak ölçüde tutulur. Dolumdan önce kavanoz ve kapaklar kontrol edilir, parti tarihi kayıt altına alınır.'),
 ('kirik-tas-kaya-tuzu-blogu-kristal-603','Dağ taş ustaları','Kayanın içinden çıkan yalın kristal','Kristal tuz bloğunda değer, kanıtsız mineral ya da sağlık iddiası kurmakta değildir. Parça önce çatlak, yüzey ve kullanım güvenliği açısından incelenir; gevşek kırıntılar temizlenir, keskin kenarlar gerektiği kadar düzenlenir. Doğal renk ve damar farklılıkları saklanmaz, ürün olduğu haliyle ve açık kullanım bilgisiyle sunulur.'),
 ('kislik-kurutulmus-cennet-hurmasi-808','Köy kiler kadınları','Turuncu sonbaharın kışa asılan tatlı hatırası','Cennet hurmaları kurutmaya girmeden önce olgunluk ve yüzey bütünlüğüne göre seçilir. Askıda ya da sergide hava dolaşımı korunur, yumuşayan ve bozulma riski taşıyan meyve ayrılır. Sabırla su kaybeden hurmalar paketlenmeden önce yeniden kontrol edilir; doğal renk farklılıkları ürünün mevsim izidir.'),
 ('kitir-taze-cagla-badem-806','Bademli Köyü Çiftçiliği','İlkbaharın ilk kıtır habercisi','Çağlanın sezonu kısadır; bu yüzden hasat günü ürünün bütün hikâyesini belirler. Çok küçük olan bekletilir, sertleşmeye başlayan ayrı tutulur. Toplanan çağlalar gölgede hızla ayıklanır ve su kaybını azaltacak şekilde hazırlanır. Amaç ilkbaharın o kısa kıtır penceresini kutuya mümkün olduğunca canlı taşımaktır.'),
 ('koylu-isi-aci-kirmizi-biber-706','Zeliş Abla','Yaz güneşinin kilerde kalan kırmızı ateşi','Zeliş Abla biberi renk kadar koku ve et kalınlığına göre de ayırır. Kurutma için açılan ürünler nem tutmayacak biçimde serilir; güneş fazla sertleşirse gölgeye alınır. Öğütme ya da paketleme öncesinde sap, yabancı madde ve nem kontrolü tekrar yapılır, böylece acılık tek başına kalite ölçüsü sayılmaz.'),
 ('koyun-efsanevi-beyaz-isitma-pres-tasi-402','Köy evlerinin ustaları','Kış evinin sessizce ısı tutan beyaz taşı','Beyaz taş seçilirken çatlak, yüzey bütünlüğü ve ısıyla temas edecek bölüm dikkatle incelenir. Her doğal parça aynı damar ve ağırlıkta olmaz; bu farklılıklar gizlenmez. Kullanım amacı dekoratif ya da geleneksel ısı tutma pratiği olabilir, ancak güvenli kullanım sınırları ayrıca açık biçimde anlatılır.'),
 ('kusburnu-marmelati-707','Oremar Kadın Üretici Grubu','Sonbaharın dikenli çalıdan kavanoza giren kızıl emeği','Kuşburnu toplamak, ayıklamak kadar sabır ister. Oremar Kadın Üretici Grubu meyveyi sap ve bozuk tanelerden temizler, yumuşatma sonrası çekirdek ve posa ayrımını tekrar tekrar süzer. Kıvam gereğinden fazla koyulaştırılmadan takip edilir; kavanozlama küçük partiler halinde tamamlanır.'),
 ('merez-hatun-un-magara-tulum-peyniri-201','Merez Hatun','Serin karanlıkta ağır ağır karakter kazanan peynir','Merez Hatun için tulum peynirinin asıl işi mayalamadan sonra başlar. Süzme, tuzlama, tuluma yerleştirme ve dinlendirme aşamaları birbirini takip eder; serin ortamın dengesi düzenli kontrol edilir. Peynir olgunlaşırken her parça aynı görünmese de doku ve koku gelişimi izlenir, parti bilgisi korunur.'),
 ('naciye-nin-yayik-tereyagi-202','Naciye Teyze','Tahta yayığın ritminden çıkan sarı beyaz miras','Naciye Teyze yayıkta yalnız süre tutmaz; sesin değişmesini, yağın toparlanmasını ve suyun berraklaşmasını birlikte izler. Tereyağı ayrıldıktan sonra küçük partiler halinde yıkanır ve fazla suyunu bırakması beklenir. Paketleme, ürünün kokusunu başka malzemelerden koruyacak biçimde yapılır.'),
 ('sabir-kurutmasi-cicek-bamyasi-702','Köy kadınları','Yazın ince parmak emeğini kışa taşıyan sabır','Çiçek bamya küçükken değerlidir ama aynı zamanda çok hassastır. Köy kadınları taneleri tek tek ayırır, ipe dizerken ezmemeye dikkat eder ve kurutma boyunca nemli kalan bölümleri kontrol eder. Paketlemeye gelene kadar birçok kez elden geçen ürün, kış yemeğinde dağılmadan kalabilmesi için özenle saklanır.'),
 ('salih-in-meralik-ozgur-horozu-304','Kümenci Salih Dayı','Meralık yaşamın sofraya bıraktığı güçlü karakter','Salih Dayı horozların hareketini, yemini ve günlük bakımını düzenli izler. Hazırlık aşamasında temizlik, soğutma ve paketleme birbirinden kopuk düşünülmez. Ürün standart bir endüstri kalıbına benzesin diye zorlanmaz; ağırlık ve doğal yapı farklılıkları sipariş bilgisinin parçası olarak açık tutulur.'),
 ('sami-usta-nin-kurutulmus-dag-dutlari-502','Sami Usta','Yaz güneşinin duttan çektiği koyu tatlılık','Sami Usta dutu silkelerken yere düşen her taneyi aynı torbaya atmaz; sağlam ve doğru olgunluktaki meyveler ayrılır. Kurutma sırasında güneşin sertliği ve gece nemi takip edilir, gerekirse ürün içeri alınır. Paketleme öncesi yapışmış kümeler nazikçe ayrılır ve fazla nemli taneler elenir.'),
 ('sessiz-orman-kuzu-gobegi-mantari-601','Orman Sakallıları','İlkbaharın ormanda kısa süre görünen sessiz armağanı','Kuzu göbeği mantarının zamanı kısa, çıktığı yer hassastır. Orman Sakallıları doğadan toplarken küçük ve gelişmemiş örnekleri bırakır, ezilmiş veya uygun olmayanları ayırır. Siparişte iri bütün ağırlıklı ya da karışık boy seçimi ile tek paket veya küçük porsiyon düzeni belirlenebilir.'),
 ('sobalik-mese-yarigi-403','Köy Ormancıları','Kış sobasının ağır ve tok meşe hazırlığı','Sobalık meşede yalnız odunun cinsi değil, kuruluk ve yarma ölçüsü de önemlidir. Köy Ormancıları çatlak yönünü okuyarak parçaları kullanım boyuna getirir, fazla nemli olanları satış partisine karıştırmaz. İstifleme hava alacak biçimde yapılır ve taşıma öncesinde gevşek kabuk ile kırıntı yeniden temizlenir.'),
 ('taze-yayik-ayrani-canli-kultur-205','Köy yayık ustaları','Sofraya köpüğüyle gelen eski yayık geleneği','Yayık ayranında kıvam, sıcaklık ve tazelik aynı anda yönetilir. Yoğurdun suyla buluşma oranı partiye göre kontrol edilir, yayık süresi köpüğü ve dokuyu bozmayacak şekilde tutulur. Dolum sonrası ürün bekletilmeden uygun saklama akışına alınır; güvenli tüketim ve soğuk zincir bilgisi ayrıca gösterilir.'),
 ('yuksekova-yayla-domatesi-802','Hakkari Tarım Kooperatifi','Yaz güneşinin yaylada ağır ağır kızarttığı domates','Yayla domatesi toplanırken sadece kırmızı renge bakılmaz; sap, kabuk direnci ve taşıma olgunluğu birlikte değerlendirilir. Çok yumuşak olanlar yerel kullanım için ayrılır, yolculuğa uygun ürünler kasada üst üste ezilmeyecek biçimde dizilir. Her sevkiyat, o haftanın hava ve hasat koşulunu taşır.'),
 ('zahter-harmani-dag-kekigi-507','Dağ otu toplayıcıları','Yüksek yamacın avuca sığan keskin kokusu','Zahter ve dağ kekiği toplamada çiçeklenme anı ile günün saati önemlidir. Bitki kökünden sökülmeden uygun dallar seçilir; gölgeli ve hava alan ortamda kurutma yapılır. Yaprak ve çiçekler ufalanmadan önce yabancı parçalar ayıklanır, kokusunu koruyacak küçük paketlere alınır.')
), source as (
 select p.id,p.slug,p.name,coalesce(nullif(btrim(p.origin),''),'kayıtlı üretim coğrafyasında') as origin,e.persona,e.seasonal_hook,e.craft_detail
 from public.products p
 join editorial e on e.slug=p.slug
 where p.status='published' and p.is_active=true and p.deleted_at is null
), stories as (
 select id,slug,
   seasonal_hook||'. '||origin||' çevresinde '||name||' hazırlanırken '||persona||' için ilk kural ürünü zorlamak değil, onun zamanını ve malzemenin verdiği işaretleri okumaktır. '||
   'Bu işin inceliği bir tarif kâğıdından çok, köyde kendinden önce yapan insanların yanında görerek, sorarak ve tekrar ederek öğrenilen küçük ayrıntılarda yaşar. Havanın değişimi, suyun sertliği, toprağın kokusu, ürünün dokusu ve yolculuğa ne kadar dayanacağı aynı hazırlığın parçaları kabul edilir. '||
   craft_detail||' '||
   'Golden Oremar bu demo anlatıda ürünü efsaneleştirmek yerine emeğin neden zaman aldığını görünür kılar. Küçük parti yaklaşımı ayıklama, dinlendirme, hazırlama ve paketleme aşamalarının gözle yeniden kontrol edilmesini sağlar. Mevsime bağlı doğal farklılıklar saklanmaz; renk, boy veya doku her seferinde milimetrik olarak aynı olmayabilir. Sipariş hazırlanırken ürünün gerçek niteliği, kayıtlı menşei ve uygulanabilir müşteri tercihleri korunur. Kutuyu açtığınızda amaç yalnızca güzel bir ürün görmek değil, üretildiği yerin mevsimini, insan elinin dikkatini ve köy bilgisinin sade mantığını mümkün olduğunca bozmadan sofranıza taşımaktır.' as story
 from source
)
update public.products p
set story=s.story,updated_at=timezone('utc',now())
from stories s
where p.id=s.id;

do $$
declare missing_count integer; short_count integer;
begin
  select count(*) into missing_count
  from public.products p
  where p.status='published' and p.is_active=true and p.deleted_at is null
    and p.slug in (
      'abidin-in-yayla-kuzusu-302','amine-nin-cifte-sari-koy-yumurtasi-305','ata-tohumu-dag-kekigi-suyu-distile-807','avasin-cam-damacana-suyu-401','avasin-deresi-canli-alabaligi-ozel-hasat-301','avasin-mese-bali-103','bercelan-yaylasi-bahar-cicek-bali-102','buyuk-iskender-corek-otu-tohumu-705','dag-cilegi-yabani-803','daglica-karakovan-petek-bali-101','eksi-karadut-suyu-804','el-isciligi-mese-palamudu-ekmegi-505','el-islemesi-tahta-kasik-ve-yayik-tokmagi-704','fahrettin-in-sutten-kesilmis-oglagi-303','gunes-sirri-guzu-yagi-ic-yag-701','gunluk-taze-civik-sut-sagimdan-kapiya-204','hakkari-dag-elmasi-801','hardaliye-geleneksel-805','hatun-ana-nin-eksi-maya-gunesi-tarhana-501','havahan-in-otlu-dag-peyniri-203','husnu-dayi-nin-kagit-kabuklu-cevizi-504','isli-kaya-uzumleri-tane-kuru-506','kadin-imecesi-odun-atesi-pekmezi-503','kan-kirmizi-yabani-kizilcik-surubu-seti-602','kekik-aromali-kesik-yogurt-kurud-703','kekik-aromali-visne-kompostosu-809','kirik-tas-kaya-tuzu-blogu-kristal-603','kislik-kurutulmus-cennet-hurmasi-808','kitir-taze-cagla-badem-806','koylu-isi-aci-kirmizi-biber-706','koyun-efsanevi-beyaz-isitma-pres-tasi-402','kusburnu-marmelati-707','merez-hatun-un-magara-tulum-peyniri-201','naciye-nin-yayik-tereyagi-202','sabir-kurutmasi-cicek-bamyasi-702','salih-in-meralik-ozgur-horozu-304','sami-usta-nin-kurutulmus-dag-dutlari-502','sessiz-orman-kuzu-gobegi-mantari-601','sobalik-mese-yarigi-403','taze-yayik-ayrani-canli-kultur-205','yuksekova-yayla-domatesi-802','zahter-harmani-dag-kekigi-507'
    ) and coalesce(char_length(p.story),0)<500;
  select count(*) into short_count from public.products p where p.status='published' and p.is_active=true and p.deleted_at is null and coalesce(char_length(p.story),0)<500;
  if missing_count<>0 then raise exception 'premium_demo_story_seed_failed:%',missing_count; end if;
  if short_count<>0 then raise exception 'published_product_story_minimum_failed:%',short_count; end if;
end;
$$;
